// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/core/MonetrixVault.sol";

contract AuditAgentPoC is SimulatorBase {
    // ATTACK TIMELINE:
    // 1. [Setup] SimulatorBase deploys the full protocol. We fund the RedeemEscrow with 1000 USDC to simulate vault funding.
    // 2. [T=1] Simulate the desync bug: The Vault records a redeem request for 100 USDC, but due to a rounding/logic bug, it calls addObligation(150 USDC) on the RedeemEscrow.
    // 3. [T=2] State changes: RedeemEscrow.totalOwed becomes 150 USDC, while actual obligation is only 100 USDC. Escrow balance is 1000 USDC.
    // 4. [T=3] The Vault attempts to reclaim the true excess (900 USDC) via reclaimTo.
    // 5. [Assert] reclaimTo reverts because balance (1000) < amount (900) + totalOwed (150). The 50 USDC difference is permanently locked in the escrow with no reconciliation mechanism.

    function test_exploit() public {
        console.log("=== Starting test_exploit ===");
        console.log("block.timestamp:", block.timestamp);
        console.log("address(usdc):", address(usdc));
        console.log("address(redeemEscrow):", address(redeemEscrow));
        console.log("address(vault):", address(vault));

        // 1. Setup: Fund the RedeemEscrow with 1000 USDC (simulating Vault.fundRedemptions)
        uint256 escrowFunding = 1000e6;
        console.log("escrowFunding:", escrowFunding);

        console.log("Before deal - Escrow USDC balance:", usdc.balanceOf(address(redeemEscrow)));
        deal(address(usdc), address(redeemEscrow), escrowFunding);
        console.log("After deal - Escrow USDC balance:", usdc.balanceOf(address(redeemEscrow)));

        uint256 balBefore = usdc.balanceOf(address(redeemEscrow));
        console.log("Step 1: Escrow balance =", balBefore);
        assertEq(balBefore, escrowFunding, "Escrow should be funded");

        // 2. Simulate the desync bug: Vault over-reports obligation to Escrow
        // Actual request recorded in Vault is 100 USDC, but addObligation is called with 150 USDC
        uint256 actualObligation = 100e6;
        uint256 buggedObligation = 150e6;

        console.log("Before addObligation - totalOwed:", redeemEscrow.totalOwed());
        console.log("Pranking address(vault):", address(vault));
        vm.prank(address(vault));
        redeemEscrow.addObligation(buggedObligation);
        console.log("After addObligation - call succeeded");

        uint256 totalOwed = redeemEscrow.totalOwed();
        console.log("Step 2: totalOwed after addObligation =", totalOwed);
        assertEq(totalOwed, buggedObligation, "totalOwed should reflect the bugged amount");

        // 3. Calculate the true excess that the Vault SHOULD be able to reclaim
        // True excess = Balance - Actual Obligation = 1000 - 100 = 900
        uint256 trueExcess = escrowFunding - actualObligation;
        console.log("Step 3: True excess to reclaim =", trueExcess);

        // 4. Vault attempts to reclaim the true excess (900 USDC)
        // The guard in RedeemEscrow is: require(balance >= amount + totalOwed)
        // 1000 >= 900 + 150 => 1000 >= 1050 (FALSE)
        console.log("Before reclaimTo - Escrow USDC balance:", usdc.balanceOf(address(redeemEscrow)));
        console.log("Before reclaimTo - totalOwed:", redeemEscrow.totalOwed());
        console.log("Before reclaimTo - trueExcess (amount):", trueExcess);

        console.log("Pranking address(vault) for reclaimTo:", address(vault));
        vm.prank(address(vault));
        vm.expectRevert();
        redeemEscrow.reclaimTo(address(vault), trueExcess);
        console.log("After reclaimTo - expectRevert caught the revert successfully");

        console.log("Step 4: reclaimTo reverted as expected due to desync");

        // 5. Prove that the funds are permanently locked
        // The maximum the vault can reclaim is balance - totalOwed = 1000 - 150 = 850
        // This leaves 50 USDC (the desync amount) permanently locked in the escrow
        uint256 maxReclaimable = escrowFunding - totalOwed;
        uint256 lockedFunds = trueExcess - maxReclaimable;

        console.log("Step 5: Max reclaimable =", maxReclaimable);
        console.log("Step 5: Permanently locked funds =", lockedFunds);

        assertGt(lockedFunds, 0, "Funds are permanently locked due to totalOwed desync");
        assertEq(lockedFunds, buggedObligation - actualObligation, "Locked amount equals the desync delta");

        console.log("=== test_exploit finished successfully ===");
    }
}
